def codex_model(model: str, env: dict[str, str]) -> str:
    for tier, default in (
        ("sonnet", "gpt-6.1-sol"),
        ("opus", "gpt-6.1-sol"),
        ("haiku", "gpt-6-luna"),
    ):
        if model == tier or model.startswith(f"claude-{tier}-"):
